package com.finanscore.credit.application;
import com.finanscore.credit.domain.*;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import com.finanscore.credit.infrastructure.*;import com.finanscore.support.observability.ObservabilityContext;import com.finanscore.support.outbox.OutboxService;import io.opentelemetry.instrumentation.annotations.WithSpan;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service public class CreditRequestService{private static final Logger log=LoggerFactory.getLogger(CreditRequestService.class);private final CreditRequestRepository repo;private final OutboxService outbox;public CreditRequestService(CreditRequestRepository r,OutboxService outbox){repo=r;this.outbox=outbox;}
 @WithSpan("create-credit-request") @Transactional public CreditRequestEntity create(Long userId,String correlationId,String product,BigDecimal amount,int term,String purpose,boolean consent){if(!consent)throw new IllegalArgumentException("Debe autorizar la consulta de información crediticia.");validate(product,amount,term);UUID requestId=UUID.randomUUID();String corr=(correlationId==null||correlationId.isBlank())?UUID.randomUUID().toString():correlationId;try(var ignored=ObservabilityContext.bind(requestId.toString(),corr,null)){var x=new CreditRequestEntity();x.id=requestId;x.userId=userId;x.correlationId=corr;x.productCode=product;x.amount=amount;x.currency="PEN";x.termMonths=term;x.purpose=purpose;x.consent=true;x.status=CreditRequestStatus.AWAITING_PAYMENT;x.createdAt=x.updatedAt=Instant.now();var saved=repo.save(x);Map<String,Object> payload=new LinkedHashMap<>();payload.put("requestId",x.id.toString());payload.put("userId",x.userId);payload.put("productCode",x.productCode);payload.put("amount",x.amount);payload.put("currency",x.currency);payload.put("termMonths",x.termMonths);payload.put("purpose",x.purpose);outbox.append("CreditRequestCreated",x.id.toString(),x.correlationId,null,null,"credit-service",payload);log.info("Credit request created status={} product={} amount={}",x.status,x.productCode,x.amount);return saved;}}
 private void validate(String p,BigDecimal a,int t){Map<String,BigDecimal[]> m=Map.of("PRESTAMO_PERSONAL",new BigDecimal[]{new BigDecimal("1000"),new BigDecimal("50000"),new BigDecimal("6"),new BigDecimal("48")},"CREDITO_EDUCATIVO",new BigDecimal[]{new BigDecimal("1000"),new BigDecimal("80000"),new BigDecimal("6"),new BigDecimal("60")},"CREDITO_VEHICULAR",new BigDecimal[]{new BigDecimal("5000"),new BigDecimal("150000"),new BigDecimal("12"),new BigDecimal("72")},"CAPITAL_TRABAJO",new BigDecimal[]{new BigDecimal("2000"),new BigDecimal("100000"),new BigDecimal("6"),new BigDecimal("48")});var r=m.get(p);if(r==null)throw new IllegalArgumentException("Producto no soportado.");if(a.compareTo(r[0])<0||a.compareTo(r[1])>0)throw new IllegalArgumentException("Monto fuera del rango del producto.");if(t<r[2].intValue()||t>r[3].intValue())throw new IllegalArgumentException("Plazo fuera del rango del producto.");}}
